import { useState, useEffect } from "react";
import api from "../api";

function GroceryPage() {
  const [data, setData] = useState("");
  const [loading, setLoading] = useState(false);
  const [families, setFamilies] = useState([]);
  const [selectedFamily, setSelectedFamily] = useState(null);

  useEffect(() => {
    loadFamilies();
  }, []);

  useEffect(() => {
    if (selectedFamily) {
      loadGrocery();
    }
  }, [selectedFamily]);

  const loadFamilies = async () => {
    const res = await api.get("/families/");
    setFamilies(res.data);
    if (res.data && res.data.length > 0) {
      setSelectedFamily(res.data[0].id);
    }
  };

  const loadGrocery = async () => {
    if (!selectedFamily) return;
    setLoading(true);
    try {
      const res = await api.get(`/families/${selectedFamily}/weekly-grocery`);
      setData(res.data.items);
    } catch (error) {
      console.error(error);
      setData("Failed to load or generate groceries. Please try again.");
    }
    setLoading(false);
  };

  return (
    <div className="page">
      <h1>Weekly Grocery List</h1>
      
      {families.length > 0 && (
        <select 
          value={selectedFamily || ""} 
          onChange={e => setSelectedFamily(e.target.value)}
          style={{ marginBottom: "20px" }}
        >
          {families.map(f => (
            <option key={f.id} value={f.id}>{f.name}</option>
          ))}
        </select>
      )}

      {loading ? (
        <p>Loading or generating grocery list for the current week... Please wait.</p>
      ) : (
        <div className="card pre">
          {data || "No grocery list found."}
        </div>
      )}
    </div>
  );
}

export default GroceryPage;
